void Solver::bump_var(int var, double coeff) {
    activity[var] += var_inc * coeff;
    if (activity[var] > 1e100) {
        for (int v = 1; v <= vars; v++) {
            activity[v] *= 1e-100;
        }
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

